style.css:
@-moz-document domain("chat.openai.com") {
/* Fondo rosado suave */
  body {
    background-color: #ffc0cb !important;
  }

  /* Cambiar el color de los botones a rosa */
  button, 
  .btn, 
  .chat-input__textarea, 
  .scroll-hide {
    background-color: #ff69b4 !important; /* rosa fuerte */
    color: white !important;
  }

  /* Cambiar color de texto */
  .text-base, 
  .chat-line__message {
    color: #d147a3 !important; /* rosa oscuro */
  }

  /* Cambiar barra lateral (sidebar) */
  .sidebar {
    background-color: #ffb6c1 !important; /* rosa claro */
  }
}
